import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key not found in path: {key}")
    def extract_numbers(obj):
        nums = []
        if isinstance(obj, (int, float, np.number)):
            nums.append(float(obj))
        elif isinstance(obj, str):
            s = obj.strip()
            if not s:
                return []
            try:
                nums.append(float(s))
            except ValueError:
                pass
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                nums.extend(extract_numbers(item))
        elif isinstance(obj, dict):
            for v in obj.values():
                nums.extend(extract_numbers(v))
        return nums
    values = extract_numbers(current)
    if not values:
        raise ValueError("No numeric data found")
    df = pd.DataFrame({"values": values})
    fig, ax = plt.subplots()
    sns.boxplot(y="values", data=df, ax=ax)
    ax.set_title("Boxplot of Extracted Data")
    return fig
